"""Contexto de entrada, linguagem, leitura de imagem e práticas orais do 10.º ano."""
CONTEXT={
'01':dict(
 image='publico',caption='Joseph Wright of Derby, Uma experiência com uma ave numa bomba de ar, 1768. A imagem abre uma pergunta sobre quem observa e quem pode intervir; não representa uma cena de Truman.',
 alt='Um grupo de adultos e crianças observa uma experiência com uma ave num recipiente de vidro, iluminada ao centro.',
 hook='Quando uma pessoa está em perigo, o que muda entre olhar e intervir?',
 chapters=[
 ('O mundo de Truman','The Truman Show é um filme de Peter Weir, de 1998. Truman Burbank vive em Seahaven. Julga ter uma vida comum: trabalha, é casado e tem amigos. O público do filme descobre que a cidade é um enorme cenário. As pessoas à sua volta representam papéis e a sua vida é transmitida na televisão. Truman é a única pessoa que não sabe.'),
 ('Quem está em cena','Christof dirige o programa e decide o que Truman pode ver. Meryl representa a mulher e Marlon o melhor amigo. Sylvia é uma participante que tenta dizer-lhe a verdade. Para Truman, estas relações são a sua vida. Para a produção, são também meios de manter o espetáculo. Esta diferença permite perguntar quando uma relação se transforma em instrumento de controlo.'),
 ('O problema de cidadania','Truman tem conforto, mas falta-lhe informação para decidir se aceita aquela vida. Uma escolha livre exige conhecer a situação e ter uma possibilidade real de agir. A pergunta não é apenas «ele parece feliz?». É também «pode escolher?». Durante a tempestade, Christof cria um perigo para impedir a saída: a proteção que invoca entra em conflito com aquilo que faz.')],
 words=[('Consentimento','Aceitação livre de uma situação que a pessoa compreende.','Truman não conhece o programa e, por isso, não o aceitou de forma informada.'),('Autonomia','Capacidade de orientar a própria vida e fazer escolhas.','Poder escolher outro caminho, mesmo que a produção discorde.'),('Responsabilidade','Ter de responder pelas escolhas e pelos seus efeitos.','Quem controla a tempestade tem de responder pelo perigo que cria.')],
 observe=[('Olhares','Segue os olhos e os gestos. As pessoas assistem à mesma experiência, mas as reações são diferentes. Uma posição junto do acontecimento não revela, por si só, o que alguém sente.'),('Centro de atenção','A luz destaca a experiência. A pessoa que controla o aparelho concentra uma possibilidade de ação que os outros não têm da mesma forma.'),('Intervenção','Pergunta quem pode alterar o que acontece. A pintura permite abrir o problema; não demonstra como as personagens de Truman agiriam.')],
 bridge=('No filme','Christof pode controlar acontecimentos que Truman nem sequer sabe serem produzidos.','Na cidadania','O poder sobre outra pessoa exige justificação, limites e possibilidade de contestação.','Ter autoridade para organizar algo não torna qualquer decisão legítima.'),
 oral=[('Leitura sentada','Texto original para duas vozes: A — «Está tudo preparado para ti.» B — «Então porque não me dizes o que está a acontecer?» Lê primeiro como cuidado e depois como controlo. Que mudança de voz alterou o sentido?'),('Imagem de grupo','Três voluntários representam quem decide, quem é afetado e quem assiste. Fazem uma imagem fixa. O grupo altera apenas uma posição para mostrar uma possibilidade de intervenção.'),('Debate de posições','Distribui as posições «produção», «Truman» e «público». Cada grupo indica uma informação de que precisa antes de decidir. Depois, identifica um direito que nenhuma posição pode ignorar.')],
 review=('Truman vive uma vida organizada por outros sem saber disso.','O problema é a relação entre informação, liberdade e poder.','Compara o que Christof afirma com aquilo que faz.'),
 essay=('Christof diz que protege Truman, mas controla a informação e os meios de saída.','Sem conhecer a situação nem poder sair, Truman não consegue decidir sobre a própria vida.','A liberdade exige mais do que conforto: exige informação e possibilidade real de escolha.'),
 check=('Se Truman tem casa e amigos, porque continua a haver um problema de liberdade?','Porque o conforto não substitui conhecer a situação e poder recusá-la.'),refs=['direitos','abramovic']),

'02':dict(
 image='caverna',caption='Jan Saenredam, segundo Cornelis van Haarlem, A caverna de Platão, 1604. Uma gravura posterior torna visível a situação imaginada por Platão.',
 alt='Gravura da caverna: pessoas sentadas observam sombras, enquanto outras figuras e uma fonte de luz ficam atrás delas.',hook='E se a tua explicação do mundo dependesse daquilo que nunca pudeste ver?',
 chapters=[
 ('Uma história para pensar','Platão foi um filósofo da Grécia antiga. Na República, imagina pessoas presas numa caverna desde a infância. Só podem olhar em frente. Veem sombras numa parede e tomam-nas pela realidade. Atrás delas existem objetos e uma fonte de luz que desconhecem. A situação não é um relato histórico: é uma alegoria, uma história que ajuda a pensar um problema.'),
 ('Sair não resolve tudo de repente','A saída obriga a pessoa a rever aquilo em que acreditava. O desconhecido pode causar desconforto, e uma explicação familiar pode parecer mais segura. Truman também encontra falhas num mundo que sempre lhe pareceu normal. O primeiro passo é reconhecer que uma observação pode admitir várias explicações e que precisamos de investigar antes de concluir.'),
 ('Da caverna ao palco','CHIROPTERA é um projeto de JR, Damien Jalet e Thomas Bangalter, apresentado em Paris em 2023. A fachada do Palais Garnier foi transformada numa caverna e num espaço de dança. Corpos, sombras, luz e som construíram uma experiência coletiva. A relação com Platão é uma interpretação artística: não é preciso procurar uma tradução exata de cada figura da alegoria.')],
 words=[('Alegoria','História ou imagem que ajuda a pensar uma ideia através de outra situação.','A caverna permite discutir os limites daquilo que sabemos.'),('Hipótese','Explicação possível que ainda precisa de ser testada.','Talvez alguém esteja a organizar os movimentos à volta de Truman.'),('Evidência','Informação que pode sustentar ou contrariar uma explicação.','Uma emissão de rádio acompanha aquilo que Truman faz.'),('Inferência','Conclusão a que chegamos a partir de indícios.','Concluir que existe organização a partir de vários acontecimentos relacionados.')],
 observe=[('As posições','Localiza quem vê a parede e quem se encontra atrás. Duas pessoas no mesmo espaço podem ter acesso a informações muito diferentes.'),('O mecanismo','Procura a relação entre luz, objetos e sombras. Para compreender o efeito visível, pode ser preciso conhecer o mecanismo que o produz.'),('O limite','A gravura é uma interpretação da alegoria. Observar esta imagem não nos dá, por si só, uma descrição de todas as sociedades ou de todas as pessoas.')],
 bridge=('Na caverna','As pessoas só conhecem uma parte da situação e não conseguem ver como essa imagem é produzida.','Em Seahaven','Truman conhece os acontecimentos, mas desconhece a estrutura que os organiza.','Ter acesso a uma parte não é o mesmo que compreender o conjunto.'),
 oral=[('Leitura sentada','Texto original: «Vejo três pessoas passarem todos os dias à mesma hora.» Outra voz propõe duas explicações diferentes. A turma separa o que foi observado das hipóteses.'),('Imagem de grupo','Um grupo cria uma imagem fixa de pessoas com acesso desigual a informação. Outro grupo identifica quem sabe mais e o que teria de mudar para todos poderem perguntar.'),('Debate de posições','Duas posições: «a explicação habitual basta» e «há motivo para investigar». Cada grupo apresenta uma pista e uma pergunta, sem transformar a suspeita em certeza.')],
 review=('Platão imagina uma situação em que só se conhece uma parte.','Investigar exige distinguir o que vemos da explicação que propomos.','Relaciona a caverna com Seahaven e identifica uma diferença.'),
 essay=('Truman nota falhas nos percursos e na informação que recebe.','Esses indícios põem em causa a explicação habitual, mas precisam de ser relacionados.','Questionar uma aparência torna-se mais rigoroso quando procuramos evidências.'),
 check=('Qual é a diferença entre uma hipótese e uma observação?','A observação descreve um dado; a hipótese propõe uma explicação a testar.'),refs=['chiroptera']),

'03':dict(
 reading=('Shakespeare · O Mercador de Veneza · ato III, cena 1','Um judeu não tem olhos? Não tem um judeu mãos, órgãos, corpo, sentidos, afetos, paixões? […] Se nos picam, não sangramos? Se nos fazem cócegas, não rimos? Se nos envenenam, não morremos? E, se nos fazem mal, não havemos de nos vingar? Se somos como vós no resto, também nisso nos pareceremos.','Tradução própria de um excerto do original em domínio público. As reticências assinalam uma omissão. Procura a passagem da humanidade comum para a justificação da vingança.'),
 image='shakespeare',caption='Retrato Chandos, tradicionalmente identificado como William Shakespeare, início do século XVII. A identificação do retratado não é absolutamente segura.',
 alt='Retrato de um homem de cabelo escuro, com barba e brinco, tradicionalmente identificado como Shakespeare.',hook='O que precisa uma pessoa de ter em comum contigo para merecer os mesmos direitos?',
 chapters=[
 ('Uma pessoa não tem de ser parecida contigo','A dignidade é o valor que reconhecemos a cada pessoa por ser pessoa. Não depende de ser simpática, útil, popular ou semelhante a nós. Os direitos humanos partem deste reconhecimento. Podemos criticar uma ação e continuar a reconhecer direitos a quem a praticou. A igualdade de dignidade não significa que todas as pessoas tenham a mesma história ou as mesmas condições de vida.'),
 ('Shakespeare e Shylock','Shakespeare escreveu teatro em Inglaterra entre os séculos XVI e XVII. Em O Mercador de Veneza, Shylock é um judeu que vive num meio marcado pela hostilidade contra os judeus. No ato III, cena 1, reclama o reconhecimento de uma humanidade comum. O discurso também caminha para a vingança. A passagem obriga a discutir as duas coisas: discriminação sofrida e responsabilidade pelas ações.'),
 ('The Egg: imaginar o lugar de todos','The Egg é um conto de Andy Weir. Uma personagem descobre uma possibilidade imaginária: todas as vidas humanas estariam ligadas à sua própria existência. O conto transforma o modo como olhamos para quem é diferente ou desconhecido. É uma proposta de ficção para pensar a empatia. Não é uma demonstração científica sobre a vida ou a morte.')],
 words=[('Humanismo','Perspetiva que coloca o valor da pessoa e a sua capacidade de pensar, agir e viver com os outros no centro da reflexão.','Perguntar se o programa respeita Truman como pessoa, e não apenas como produto.'),('Dignidade','Valor de uma pessoa que não depende da sua utilidade ou popularidade.','Truman merece respeito mesmo que o público goste do programa.'),('Empatia','Procurar compreender a experiência ou o ponto de vista de outra pessoa.','Perguntar como viverias a divulgação de uma imagem tua sem autorização.'),('Discriminação','Tratamento desfavorável ligado a uma característica ou pertença.','Excluir alguém pela sua origem, em vez de avaliar a situação com critérios justos.'),('Igualdade','Reconhecimento dos mesmos direitos e da igual dignidade.','Os direitos não desaparecem quando uma pessoa é impopular.')],
 observe=[('O retrato','Distingue aquilo que a imagem mostra daquilo que sabes sobre o autor. Uma expressão pintada não demonstra o carácter nem as opiniões de alguém.'),('A identificação','A legenda indica uma atribuição tradicional, não uma certeza absoluta. A forma como uma fonte apresenta as suas dúvidas faz parte da informação.'),('Quem fala','Passa do autor para a personagem: Shakespeare escreveu Shylock, mas autor e personagem não têm de defender a mesma posição em cada fala.')],
 bridge=('Nas obras','Shylock reclama humanidade; The Egg propõe imaginar a ligação entre vidas diferentes.','Na cidadania','A igualdade de direitos não pode depender de conseguirmos gostar de toda a gente.','A empatia ajuda a compreender; a dignidade dá uma base que também vale quando a empatia falha.'),
 oral=[('Leitura sentada','Lê a passagem de Shylock apresentada em «Conhecer». Primeiro, identifica o que a personagem reclama; depois, procura o ponto em que aparece a justificação da vingança.'),('Imagem de grupo','Uma pessoa fica fora de uma imagem de grupo. O grupo altera um único gesto para mostrar inclusão. A turma pergunta se o gesto muda também a possibilidade real de participar.'),('Debate de posições','Distribui «reconhecer a injustiça» e «avaliar a reação». Cada grupo deve reconhecer uma razão do outro antes de apresentar a sua objeção.')],
 review=('Dignidade e simpatia não são a mesma coisa.','Compreender uma reação não obriga a considerá-la justa.','Relaciona um direito com um exemplo concreto, explicando o efeito sobre a pessoa.'),
 essay=('O programa expõe a intimidade de Truman sem ele o saber.','A pessoa afetada não pode aceitar ou recusar essa exposição.','O direito à vida privada protege uma possibilidade de decisão, e não apenas um desejo de esconder algo.'),
 check=('Uma pessoa perde os seus direitos por ter uma atitude de que discordamos?','Não. Podemos avaliar e responsabilizar ações sem negar a dignidade e os direitos da pessoa.'),refs=['shakespeare','egg','direitos']),

'04':dict(
 image='stanislavski',caption='Konstantin Stanislavski, fotografia de 1912. Retrato histórico do ator, encenador e investigador do trabalho do ator.',
 alt='Fotografia em tom sépia de Stanislavski, de bigode e fato, voltado para a esquerda.',hook='O que muda numa fala quando muda aquilo que a pessoa quer conseguir?',
 chapters=[
 ('Investigar o trabalho do ator','Stanislavski foi um ator e encenador russo que procurou compreender como se prepara uma representação convincente. Em vez de pensar apenas na forma de mostrar uma emoção, podemos investigar as circunstâncias da personagem, aquilo que pretende e as ações que escolhe. Este passo apresenta uma entrada nesse trabalho; uma tradição de formação não se resume a uma receita.'),
 ('Da Rússia aos Estados Unidos','O trabalho de Stanislavski chegou aos Estados Unidos através de espetáculos e de professores ligados a essa tradição. O Group Theatre, criado em 1931, desenvolveu experiências de formação e representação. No Actors Studio, Lee Strasberg aprofundou uma abordagem própria, conhecida como Método. Há uma linha de influência, mas as propostas foram discutidas e transformadas: sistema e Método não são equivalentes em todos os aspetos.'),
 ('Compreender não é aprovar','Uma personagem pode querer ser aceite e escolher enganar alguém para o conseguir. Perceber o objetivo ajuda a interpretar a ação; não decide se a ação é justa. Marlon representa um amigo para manter Truman tranquilo. Sylvia põe em causa o papel para revelar a verdade. O conhecimento da situação abre possibilidades de escolha e também uma responsabilidade.')],
 words=[('Circunstâncias','Condições da situação em que a personagem se encontra.','Quem está presente, o que aconteceu e o que a personagem sabe.'),('Objetivo','Aquilo que alguém procura alcançar.','Convencer Truman a ficar.'),('Ação','Aquilo que alguém faz para tentar alcançar um objetivo.','Tranquilizar, ameaçar, ocultar informação ou revelar a verdade.'),('Obstáculo','Aquilo que dificulta atingir o objetivo.','Truman começa a desconfiar do que o amigo lhe diz.')],
 observe=[('O documento','A fotografia permite reconhecer uma pessoa e situar um retrato histórico. Não mostra uma técnica de representação em funcionamento.'),('A expressão','Experimenta descrever a posição da mão e do rosto sem atribuir imediatamente uma emoção. Depois, distingue descrição de interpretação.'),('A investigação','Para saber como trabalhava Stanislavski, precisamos de textos, testemunhos e história da formação, além da fotografia.')],
 bridge=('Na interpretação','Procura-se perceber como circunstâncias, objetivo e ação se relacionam.','Na cidadania','Avaliam-se também os efeitos da ação sobre os direitos e as escolhas dos outros.','Explicar por que uma pessoa agiu não resolve, por si só, se devia ter agido assim.'),
 oral=[('Leitura sentada','Texto original: «Preciso que fiques aqui.» Lê para pedir ajuda, para impedir uma descoberta e para ganhar tempo. Mantém as palavras; altera o objetivo. Que pistas permitiram distinguir as ações?'),('Imagem de grupo','Cria uma imagem fixa com uma pessoa que quer sair e outra que quer que fique. Altera a distância e a orientação dos corpos. Discute o que mudou sem acrescentar falas.'),('Debate de posições','Atribui «ator», «pessoa afetada» e «equipa». Cada posição explica o que sabe e que ação pode recusar. Usa situações inventadas, não experiências pessoais que alguém tenha de revelar.')],
 review=('Objetivo é o que se pretende; ação é o que se faz.','Stanislavski e o Actors Studio estão ligados por uma história de receção e transformação.','Usa a compreensão da personagem para analisar a ação e os seus efeitos.'),
 essay=('Marlon conhece o programa e usa palavras ditadas por Christof.','A confiança da amizade torna a sua intervenção convincente para Truman.','A qualidade da representação aumenta o efeito do engano e não elimina a responsabilidade de quem representa.'),
 check=('Que diferença existe entre objetivo e ação?','O objetivo é o resultado procurado; a ação é uma forma concreta de o tentar alcançar.'),refs=['studio','strasberg']),

'05':dict(
 image='sisifo',caption='Ticiano, Sísifo, 1548–1549. O corpo e a pedra tornam visível o esforço do mito.',
 alt='Sísifo transporta uma grande pedra num terreno íngreme, com o corpo curvado sob o peso.',hook='Repetir os mesmos gestos significa sempre viver sem liberdade ou sem sentido?',
 chapters=[
 ('A pedra que volta a cair','No mito grego, Sísifo é condenado a fazer subir uma pedra que volta a cair. O esforço recomeça. O mito permite imaginar uma repetição sem conclusão. É importante distinguir a história antiga das interpretações posteriores: o mesmo objeto pode abrir perguntas diferentes conforme a forma como o lemos.'),
 ('A pergunta de Camus','Em O Mito de Sísifo, publicado em 1942, Albert Camus relaciona o mito com a procura de sentido numa existência que não nos entrega respostas prontas. Neste percurso, interessa a pergunta: que relação pode existir entre consciência, esforço e modo de viver? A leitura não transforma qualquer sofrimento numa coisa boa nem prova que as condições de vida sejam indiferentes.'),
 ('Do exemplo ao argumento','Um ensaio defende uma posição através de razões. Dizer «Truman tenta sair» identifica um acontecimento. Explicar que a tentativa mostra o valor que atribui à possibilidade de escolher já relaciona o exemplo com uma ideia. Antes de escrever, precisamos de formular a tese, escolher argumentos e considerar uma dificuldade que alguém possa levantar.')],
 words=[('Tese','Posição central que o texto procura defender.','Uma vida confortável pode não ser uma vida livre.'),('Argumento','Razão que sustenta uma posição.','Sem informação sobre a situação, não é possível aceitá-la de forma livre.'),('Exemplo','Caso concreto que ajuda a analisar uma ideia.','Os obstáculos preparados para impedir Truman de viajar.'),('Objeção','Dificuldade ou razão que pode pôr a posição em causa.','Sair de um lugar seguro também pode envolver riscos.')],
 observe=[('O esforço','Observa a relação entre corpo, pedra e inclinação. Que elementos tornam o peso visível sem que uma legenda o explique?'),('A continuação','A pintura mostra um momento. A repetição pertence ao conhecimento do mito; não vemos toda a história dentro desta imagem.'),('A comparação','Sísifo repete um esforço imposto; Truman procura sair de uma vida preparada. A relação exige reconhecer esta diferença, além de uma pergunta comum sobre consciência e escolha.')],
 bridge=('Nos casos','Sísifo e Truman permitem pensar sobre condições impostas e modos de lhes responder.','No ensaio','A comparação deve identificar uma relação, uma diferença e o que aprendemos com elas.','Uma referência não vale como ornamento: precisa de ajudar a explicar a posição.'),
 oral=[('Leitura sentada','Lê as três frases do exemplo comentado. Identifica onde termina o relato do filme e começa a explicação do que ele mostra.'),('Imagem de grupo','Faz duas imagens: «continuar porque quero» e «continuar porque não posso sair». A turma procura pistas corporais, mas reconhece que a imagem, sozinha, pode não esclarecer o consentimento.'),('Debate de posições','Uma posição defende a segurança; outra, a possibilidade de escolha. Cada grupo responde à melhor razão apresentada pelo outro. Evita atacar quem a apresentou.')],
 review=('Um exemplo precisa de uma explicação que o ligue à tese.','Uma objeção é uma dificuldade a enfrentar com razões.','O primeiro ensaio parte de Truman e usa uma posição fundamentada.'),
 essay=('A produção de Seahaven oferece rotina e conforto a Truman.','Esses benefícios coexistem com informação ocultada e obstáculos à saída.','Por isso, o conforto não basta para demonstrar liberdade, embora possa ser um elemento de uma vida boa.'),
 check=('Porque não basta incluir o nome de uma obra num ensaio?','Porque é preciso explicar como um exemplo ou uma ideia da obra sustenta o argumento.'),refs=['direitos','sisifo']),

'06':dict(
 image='tchekhov',caption='Osip Braz, retrato de Anton Tchékhov, 1898. Tchékhov é aqui o escritor ligado à reflexão sobre a construção dramática.',
 alt='Retrato de Anton Tchékhov, sentado, com óculos e barba, pintado por Osip Braz.',hook='Quando esperamos um desfecho, conseguimos ainda avaliar aquilo que o justifica?',
 chapters=[
 ('Um segundo filme, outra posição','Doze Homens em Fúria, de Sidney Lumet, estreou em 1957. Um júri de doze homens discute um processo de homicídio. Um jovem acusado não está na sala onde se decide a sua situação. Um jurado resiste a uma conclusão apressada. O filme concentra a atenção nos argumentos, nos preconceitos e nas mudanças de posição. Apresenta um júri dos Estados Unidos, não os tribunais portugueses.'),
 ('A arma na narrativa','Anton Tchékhov foi um escritor e dramaturgo russo. Numa carta de 1889, usa a imagem de uma arma colocada em cena para discutir a preparação e o desenvolvimento de uma peça. Um elemento destacado cria expectativas. A questão é o sentido que esse elemento terá na construção da obra. Uma expectativa narrativa não é uma autorização moral para produzir violência real.'),
 ('A pistola de Abramović','Em Rhythm 0, de 1974, Marina Abramović colocou objetos à disposição dos participantes, incluindo uma pistola e uma bala. A sua imobilidade e a intervenção do público levantam perguntas sobre poder e limites. Truman, pelo contrário, desconhece o programa. A comparação deve considerar esta diferença de consentimento e perguntar o que exige de quem assiste um perigo que se torna real.')],
 words=[('Expectativa','Aquilo que esperamos que aconteça a partir de pistas.','Um objeto destacado pode levar o público a esperar uma ação.'),('Prova','Elemento usado para sustentar uma afirmação sobre um facto.','Um objeto ou um depoimento precisa de ser relacionado com o que se quer demonstrar.'),('Depoimento','Declaração de alguém sobre factos que conhece ou diz conhecer.','O júri precisa de avaliar o que foi observado e em que condições.'),('Presunção de inocência','Princípio segundo o qual uma pessoa acusada é considerada inocente até a culpa ser estabelecida num processo justo.','Uma suspeita não substitui a demonstração exigida para condenar.')],
 observe=[('O retrato e a obra','O retrato ajuda a reconhecer o escritor. A ideia sobre construção dramática tem de ser investigada nos seus textos, não deduzida da expressão do rosto.'),('O nome','Neste passo, Tchékhov designa Anton Tchékhov, o dramaturgo. A referência à arma trata da construção da narrativa.'),('A passagem de contexto','Uma arma num texto, uma pistola numa performance e um objeto apresentado como prova são situações diferentes. Antes de comparar, identifica o que está em causa em cada uma.')],
 bridge=('Na narrativa','Perguntamos que efeito uma pista prepara e como se desenvolve.','Na decisão cívica','Perguntamos o que a informação permite concluir e que ação é justificável.','Aquilo que esperamos não substitui a evidência nem decide o que é justo fazer.'),
 oral=[('Leitura sentada','Texto original: A — «Já sabemos o que aconteceu.» B — «Sabemos ou estamos a supor?» Lê as duas posições e identifica a informação que cada uma teria de apresentar.'),('Imagem de grupo','Cria um grupo que decide sobre uma cadeira vazia. A cadeira representa a pessoa ausente. Altera a imagem para tornar visível a possibilidade de essa pessoa ser ouvida.'),('Debate de posições','Uma posição pede uma decisão imediata; outra pede verificação. Cada uma indica um risco da sua própria proposta e um modo de lhe responder.')],
 review=('O segundo filme centra-se numa decisão sobre uma pessoa ausente.','Uma suspeita ou expectativa não equivale a uma prova suficiente.','Na comparação com Abramović, explica a diferença de consentimento.'),
 essay=('No segundo filme, os jurados precisam de avaliar a informação antes de decidir.','A pressão para concluir rapidamente pode fazer com que uma primeira impressão seja tratada como certeza.','Um procedimento justo exige tempo e condições para examinar razões, sem transformar qualquer dúvida numa desculpa para nunca decidir.'),
 check=('A dúvida prova automaticamente que uma pessoa não praticou um ato?','Não. Questionar a suficiência da prova é diferente de demonstrar com certeza uma versão alternativa dos acontecimentos.'),refs=['filme2','lumet','chekhov','abramovic','direitos']),

'07':dict(
 image='publico',caption='Regressamos à pintura de Joseph Wright of Derby, de 1768, para observar quem controla um procedimento e quem permanece a assistir. Não é uma ilustração da peça de Pinter.',
 alt='Grupo de pessoas à volta de uma experiência: uma figura controla o aparelho e as restantes observam de posições diferentes.',hook='Se uma ordem vier «de cima», deixa de ser preciso perguntar se é justa?',
 chapters=[
 ('Uma autoridade que não se vê','Harold Pinter foi um dramaturgo britânico. Em The Dumb Waiter, conhecido em português como O Monta-Cargas ou O Serviço, Ben e Gus são dois assassinos contratados que aguardam instruções numa cave. Um monta-cargas, usado para transportar comida entre pisos, traz pedidos que tornam a situação estranha e ameaçadora. A origem e o sentido das ordens não são plenamente esclarecidos.'),
 ('As palavras e os silêncios','Numa cena, o sentido não está apenas nas palavras. Uma pausa, uma repetição ou uma resposta evitada pode alterar a relação entre as personagens. O subtexto é aquilo que podemos interpretar como intenção ou tensão para além do que é dito literalmente. A interpretação precisa de pistas; um silêncio não tem sempre o mesmo significado.'),
 ('A ordem e a responsabilidade','Uma decisão pode passar por várias pessoas: quem a toma, quem a transmite e quem a executa. Essa divisão pode tornar difícil identificar responsabilidades. A cidadania exige perguntar quem decidiu, com que fundamento e como pode a pessoa afetada contestar. Uma hierarquia não elimina a necessidade de justificar o poder e de avaliar os efeitos de uma ação.')],
 words=[('Autoridade','Poder reconhecido para tomar certas decisões.','Um encenador organiza um ensaio, mas isso não autoriza qualquer tratamento dos colegas.'),('Hierarquia','Organização em que existem diferentes posições de poder ou decisão.','Quem dirige, quem transmite instruções e quem as executa.'),('Subtexto','Intenção ou tensão que interpretamos para além do sentido literal das palavras.','«Está tudo tratado» pode tranquilizar ou fechar uma discussão.'),('Contestação','Possibilidade de questionar uma decisão e apresentar razões contra ela.','Pedir o fundamento de uma exclusão e uma oportunidade de ser ouvido.')],
 observe=[('O gesto de controlo','Identifica a pessoa junto do mecanismo. O que pode fazer que os outros não podem fazer da mesma forma?'),('A distribuição','Observa como as pessoas se agrupam. Estar perto de uma decisão não significa participar nela em condições de igualdade.'),('A analogia','A imagem ajuda a perguntar pelo poder de intervenção. Não prova como uma ordem circula na peça de Pinter ou numa organização real.')],
 bridge=('Em Pinter','Ordens, pausas e uma autoridade pouco visível produzem tensão.','Na democracia','É importante identificar decisões, pedir fundamentos e permitir contestação.','Uma explicação da ordem deve poder ser discutida por quem suporta os seus efeitos.'),
 oral=[('Leitura sentada','Texto original: A — «Disseram para não o deixares entrar.» B — «Quem disse?» A — «Disseram.» Faz uma leitura rápida e outra com pausas. Que informação permanece em falta?'),('Imagem de grupo','Quatro pessoas formam uma cadeia de transmissão de uma ordem. Uma quinta é afetada. Altera uma posição para mostrar a possibilidade de pedir uma justificação.'),('Debate de posições','Distribui «quem decide», «quem executa» e «pessoa afetada». Cada grupo indica uma responsabilidade sua, em vez de a atribuir toda a outra posição.')],
 review=('As pausas também participam no sentido de uma cena.','Uma ordem pode circular sem que a sua justificação circule com ela.','Analisa quem toma, transmite e executa a decisão.'),
 essay=('A instrução para excluir alguém chega sem fundamento identificado.','Executá-la impede a pessoa afetada de conhecer e contestar a razão da decisão.','O respeito pela autoridade deve coexistir com procedimentos que a tornem responsável.'),
 check=('Um silêncio significa sempre medo ou submissão?','Não. O sentido depende do contexto, das relações e das outras pistas da cena.'),refs=['pinter','direitos']),

'08':dict(
 image='leitura',caption='Johannes Vermeer, Rapariga a ler uma carta à janela, c. 1657–1659. Esta reprodução mostra o estado anterior ao restauro que revelou uma pintura de Cupido na parede. Não é uma imagem de Crave.',
 alt='Uma jovem lê uma carta junto de uma janela aberta; o observador não consegue ler o conteúdo da carta.',hook='Quando não conseguimos ouvir alguém, o que sabemos — e o que estamos a inventar?',
 chapters=[
 ('Uma peça feita de vozes','Sarah Kane foi uma dramaturga britânica que escreveu na década de 1990. Crave, estreada em 1998, trabalha com quatro vozes e uma construção fragmentada, em vez de apresentar tudo através de uma história linear facilmente reconhecível. Relações, desejo e sofrimento surgem através da linguagem. O primeiro trabalho do leitor é escutar e procurar relações, sem decidir demasiado cedo quem é cada voz.'),
 ('A fragmentação também constrói sentido','Uma frase interrompida ou uma mudança de voz pode deixar uma relação em aberto. É possível formular uma interpretação e mostrar as pistas que a sustentam. Também é possível reconhecer o que não conseguimos concluir. A voz dramática não equivale automaticamente à autora. A leitura de uma obra não pode ser substituída por uma explicação biográfica de todas as falas.'),
 ('Ser ouvido é diferente de ser explicado','Na vida coletiva, falamos por vezes sobre uma pessoa antes de a ouvir. As interpretações podem cristalizar em rótulos: «é assim», «nunca quer», «não consegue». Uma frase dita num momento não explica toda uma vida. A atitude mais rigorosa separa o que foi dito, a hipótese que propomos e a informação que falta perguntar.')],
 words=[('Voz dramática','Instância que fala numa obra; não é automaticamente a voz do autor.','Uma fala pode defender uma posição que o autor põe em discussão.'),('Fragmentação','Construção por partes que não apresentam todas as ligações de forma contínua.','Várias vozes podem aproximar-se, interromper-se ou deixar perguntas abertas.'),('Rótulo','Definição simplificada que passa a tratar uma pessoa como se fosse apenas uma característica.','Transformar «não quero falar agora» em «nunca quer participar».'),('Interpretação','Leitura que relaciona pistas para propor um sentido.','Explicar uma pausa com base na relação entre as personagens, reconhecendo outras possibilidades.')],
 observe=[('A informação visível','Vemos uma pessoa a ler. Não conseguimos ler a carta. A imagem distingue o acesso da personagem à informação do acesso de quem observa.'),('A hipótese','Podes imaginar o conteúdo ou a reação da leitora, mas a hipótese precisa de ser distinguida daquilo que a pintura mostra.'),('A revisão','O restauro alterou o que passou a ser visível na pintura. O exemplo lembra que uma interpretação pode mudar quando o material disponível muda.')],
 bridge=('Na leitura','Uma voz fragmentada pede atenção às palavras, às relações e ao que fica por esclarecer.','Na cidadania','A pessoa de quem falamos deve ter possibilidade de responder e de não caber no rótulo que lhe atribuímos.','Reconhecer uma incerteza pode ser uma forma de rigor e de respeito.'),
 oral=[('Leitura sentada','Texto original para três vozes: A — «Agora não.» B — «Nunca queres.» C — «Ela disse agora.» Lê e identifica a palavra que transforma uma situação numa generalização.'),('Imagem de grupo','Uma pessoa fica no centro enquanto outras falam sobre ela. Sem contacto físico, altera a imagem para mostrar o momento em que passa a poder responder.'),('Debate de posições','Uma posição apresenta uma interpretação; outra pede pistas; uma terceira procura uma explicação alternativa. Todas distinguem aquilo que sabem daquilo que supõem.')],
 review=('Uma frase não equivale a uma biografia.','Uma voz dramática não é automaticamente a autora.','Sustenta a leitura com pistas e identifica uma pergunta que permanece aberta.'),
 essay=('Um grupo interpreta o silêncio de uma pessoa como desinteresse.','Essa conclusão pode ignorar outras explicações e a possibilidade de a ouvir.','A participação exige condições para responder, além da presença física no grupo.'),
 check=('Reconhecer que não sabemos o que uma pessoa sente impede-nos de a respeitar?','Não. Podemos respeitar os seus direitos, ouvir o que quer dizer e reconhecer os limites da nossa interpretação.'),refs=['kane','kaneorig','vermeer']),

'09':dict(
 image='juri',caption='John Morgan, O júri, 1861. Uma representação britânica do século XIX, não um fotograma de Doze Homens em Fúria.',
 alt='Doze homens sentados em duas filas, com gestos e direções de olhar diferentes.',hook='Quando quase todos concordam, o que pode justificar continuar a discutir?',
 chapters=[
 ('Da escolha individual à decisão coletiva','Uma votação conta posições. Uma deliberação põe razões em confronto, permite perguntas e pode alterar as escolhas. Uma decisão democrática precisa de mais do que uma contagem: participação, informação, igualdade de tratamento e limites ao poder. Os direitos de uma pessoa não se tornam dispensáveis porque um grupo prefere ignorá-los.'),
 ('O que muda entre os jurados','Em Doze Homens em Fúria, o espaço fechado concentra os corpos, as falas e as tensões. Um ator pode tornar visível uma mudança por uma pausa, um olhar, uma deslocação ou uma resposta. Ao analisar, identifica a ação observável e explica a relação com o argumento. Um tom convincente não garante que a informação seja verdadeira.'),
 ('Sylvia e o gesto de interromper','Sylvia usa o que sabe para tentar alterar a situação de Truman. A sua intervenção ajuda a pensar a responsabilidade de quem participa num sistema e reconhece uma injustiça. CHIROPTERA oferece outra experiência de muitos corpos num espaço comum. Comparar estes casos permite perguntar quem tem voz e como uma ação individual se relaciona com uma ação coletiva.')],
 words=[('Democracia','Forma de organizar o poder político com participação, direitos, debate público e limites a quem decide.','Poder questionar uma decisão e dispor de procedimentos que protejam a igualdade.'),('Deliberação','Discussão em que se examinam razões e objeções antes de decidir.','Rever uma acusação quando surge informação que a põe em causa.'),('Maioria','Conjunto que reúne mais votos numa decisão.','A maioria indica uma distribuição de escolhas, não demonstra automaticamente a verdade.'),('Minoria','Conjunto que reúne menos votos ou uma posição menos representada.','Uma posição minoritária pode apresentar uma razão que o grupo precisa de examinar.'),('Preconceito','Juízo formado antes de avaliar adequadamente a pessoa ou a situação.','Supor que a origem de alguém demonstra como agiu num caso concreto.')],
 observe=[('As diferenças','Observa as orientações do corpo, das mãos e dos olhos. O grupo é apresentado como um conjunto de pessoas, não como uma única expressão.'),('A composição','Procura quem ocupa o centro e quem está nas margens. Distingue destaque visual de poder efetivo: a composição não prova quem decide melhor.'),('A ausência','O quadro mostra os jurados; não mostra a pessoa sobre quem decidem. Que cuidados exige decidir sobre quem não está presente?')],
 bridge=('No grupo','As pessoas podem concordar por razões diferentes ou discordar com informação relevante.','Na democracia','As razões devem poder ser discutidas e os direitos das pessoas afetadas devem ser protegidos.','Rever uma posição pode mostrar rigor, e não uma derrota pessoal.'),
 oral=[('Leitura sentada','Texto original: A — «Somos nove a pensar assim.» B — «Qual é a razão que os nove apresentam?» C — «Ainda não ouvimos a pessoa afetada.» Distingue contagem, fundamento e participação.'),('Imagem de grupo','Cria uma imagem de decisão coletiva com uma posição minoritária. Altera apenas a orientação dos olhares para mostrar uma passagem de isolamento a escuta.'),('Debate de posições','Cada grupo recebe uma posição. Antes da resposta, deve resumir fielmente o argumento anterior. A turma assinala quando alguém responde à razão apresentada e quando muda de assunto.')],
 review=('Contar votos e discutir razões são ações diferentes.','Maioria e verdade não são sinónimos; discordância também precisa de fundamento.','Analisa informação, procedimentos e direitos na mesma decisão.'),
 essay=('O grupo quer excluir alguém com base numa imagem incompleta.','A maioria de votos não corrige a falta de verificação nem a ausência da pessoa acusada.','A legitimidade de uma decisão depende também do procedimento que a tornou possível.'),
 check=('Uma posição minoritária é sempre mais justa?','Não. Deve ser examinada pelas razões e evidências que apresenta, tal como uma posição maioritária.'),refs=['filme2','direitos','chiroptera']),

'10':dict(
 image='caverna',caption='Regressamos à gravura da caverna, de 1604. Agora, a pergunta é como mostrar o caminho entre uma fonte, uma interpretação e uma conclusão.',
 alt='Gravura da caverna de Platão, retomada para distinguir o que está visível do mecanismo que o produz.',hook='Consegues mostrar a outra pessoa como chegaste à tua conclusão?',
 chapters=[
 ('Uma fonte responde a uma pergunta','Uma fonte pode ser um texto, uma imagem, uma instituição, uma obra ou um testemunho. O seu valor depende também da pergunta. Uma cena é adequada para analisar uma escolha de representação; não demonstra, por si só, onde um ator estudou. Uma página institucional informa sobre a instituição, mas convém reconhecer a perspetiva que apresenta.'),
 ('Verificar inclui procurar o que contraria','Se procurarmos apenas informação que confirma a nossa opinião, podemos ignorar uma dificuldade importante. A investigação compara fontes, distingue factos e interpretações e identifica o que ainda falta saber. Uma objeção bem escolhida ajuda o ensaio: mostra uma razão a que a tese precisa de responder, em vez de inventar um adversário fácil de derrotar.'),
 ('Escrever depois de compreender','O segundo ensaio relaciona os dois filmes e uma terceira referência. Começa por uma pergunta precisa. Formula a tese, apresenta dois argumentos e escolhe exemplos que os sustentem. Explica uma diferença entre as obras e responde a uma objeção. Na conclusão, mostra o que a análise permite afirmar sobre dignidade, liberdade ou responsabilidade numa sociedade democrática.')],
 words=[('Fonte primária','Material diretamente ligado ao objeto ou ao acontecimento estudado.','O filme para analisar uma cena; a carta de Tchékhov para verificar o que escreveu.'),('Fonte secundária','Material que analisa ou interpreta outras fontes.','Um estudo histórico sobre a formação de atores.'),('Viés de confirmação','Tendência para privilegiar aquilo que confirma uma ideia que já temos.','Ignorar um dado contrário e guardar apenas os exemplos favoráveis.'),('Referência','Identificação que permite encontrar uma fonte.','Autor ou instituição, título, data quando disponível e ligação.')],
 observe=[('A origem','A mesma gravura pode servir perguntas diferentes. Regista quem a produziu e em que data para não a apresentar como desenho feito pelo próprio Platão.'),('A interpretação','Distingue a informação sobre a imagem da leitura que fazes dela. A tua conclusão deve mostrar as pistas em que se apoia.'),('O percurso','Volta ao início do módulo. Que questão agora consegues formular com mais precisão? A revisão deve tornar visível o raciocínio que entretanto construíste.')],
 bridge=('Na investigação','Seleciona informação adequada e reconhece os seus limites.','No ensaio','Mostra como a informação sustenta uma posição e como respondes a uma dificuldade.','Uma opinião torna-se discutível com rigor quando os outros conseguem examinar as suas razões.'),
 oral=[('Leitura sentada','Lê o exemplo comentado. Uma voz apresenta o caso; outra explica a ligação; uma terceira apresenta uma objeção. A turma verifica se estão a discutir a mesma pergunta.'),('Imagem de grupo','Três pessoas representam fonte, interpretação e conclusão. Outra pessoa introduz um dado contrário. O grupo altera a imagem para mostrar o que precisa de ser revisto.'),('Debate de posições','Cada grupo recebe uma tese. O grupo seguinte apresenta uma objeção forte e respeitosa. O primeiro grupo pode manter, limitar ou reformular a tese, desde que explique porquê.')],
 review=('Escolhe a fonte pela pergunta a que precisas de responder.','Compara os dois filmes sem os tornar equivalentes.','O ensaio final explica uma posição, os exemplos e a resposta a uma objeção.'),
 essay=('Truman não conhece o sistema que organiza a sua vida; os jurados precisam de avaliar informação sobre outra pessoa.','As situações são diferentes, mas em ambas a decisão justa depende de informação e de limites ao poder.','A proteção da dignidade exige tornar as decisões justificáveis e contestáveis.'),
 check=('Duas páginas que copiam a mesma informação são necessariamente duas confirmações independentes?','Não. É preciso verificar a origem e perceber se dependem da mesma fonte.'),refs=['studio','direitos','filme2']),
}
